    (F : bvmap 5 word) fc (m : mem) (T stack M n SB lo cnt mc : Z) (ws24 : list word) (w stj : word) (jb : list byte)
    (pre : list batch) (b0 : Z) (ents0 : list (Z * Z)),
  (1 <= n <= 2^28)%Z -> length ents0 = 1021%nat ->
  qcache_rep m (qcacheT T) (pre ++ [(b0, ents0)]) ->
